INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_NART','Nart Saga Tradition',-400,1900)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_COLARUSSO_NART','secondary scholarship','John Colarusso, Nart Sagas from the Caucasus: Myths and Legends from the Circassians, Abazas, Abkhaz, and Ubykhs (Princeton University Press, 2002)','Primary translated corpus + commentary on the Nart epic cycle and its figures (Batraz, Satana, Sosruko, Syrdon, Warzameg).'),
 ('SRC_DUMEZIL_NART','secondary scholarship','Georges Dumézil, Le livre des héros: légendes sur les Nartes / Romans de Scythie et d''alentour','Comparative analysis linking the Ossetian Nart sagas to Scytho-Sarmatian and broader Indo-European mythology; Batraz as war-god, Uastyrdzhi cult.')
INSERT INTO _e VALUES
 ('ENT_NART_SAGAS','The Narts','collective','saga-cycle hub','Nart (Ossetian/Sarmatian)','heroic-epic cycle','B','The heroic race at the center of the Caucasian Nart epic; surviving Scytho-Sarmatian-Alanic mythology attested in Ossetian, Circassian, Abkhaz and other oral versions (Colarusso 2002; Dumézil).'),
 ('ENT_NART_BATRAZ','Batraz','hero','warrior-hero','Nart (Ossetian/Sarmatian)','war, steel, storm','B','Steel-tempered chief warrior-hero of the Narts; Dumézil reads him as a Scytho-Sarmatian war-god whose steel sword cast into the sea continues the Scythian sword-cult of Herodotus''s Ares (Colarusso 2002; Dumézil).'),
 ('ENT_NART_SATANA','Satana','hero','matriarch','Nart (Ossetian/Sarmatian)','wisdom, household, counsel','B','Wise matriarch and counselor of the Narts, sister-consort within the central Nart family; Dumézil links her name to a Sarmatian/Alanic prototype (Colarusso 2002).'),
 ('ENT_NART_UASTYRDZHI','Uastyrdzhi','deity','rider-god','Nart (Ossetian/Sarmatian)','riders, warriors, travelers, men','B','Ossetian rider-god and patron of warriors and travelers, syncretized with Saint George; venerated at the festival Jeoryguba (Dumézil; Colarusso 2002).'),
 ('ENT_NART_SOSRUKO','Sosruko','hero','trickster-hero','Nart (Ossetian/Sarmatian)','fire-theft, trickery, solar','B','Trickster culture-hero (Ossetian Soslan/Sozyryko; Circassian Sosruko) born from stone, tempered like steel, famed for the theft of fire (Colarusso 2002; Dumézil).'),
 ('ENT_NART_SYRDON','Syrdon','hero','trickster','Nart (Ossetian/Sarmatian)','trickery, discord, music','B','Malicious trickster of the Narts, sower of discord and inventor of the twelve-string harp from the bones of his slain sons; the standard scholarly Loki-analogue (Colarusso 2002; Dumézil).'),
 ('ENT_NART_KURDALAGON','Kurdalagon','deity','divine smith','Nart (Ossetian/Sarmatian)','smithing, fire, metallurgy','B','Heavenly smith of the Nart cosmos who tempers heroes (Batraz, Soslan) in his forge as one tempers steel (Colarusso 2002; Dumézil).');
