INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_NART_BATRAZ','member_of','ENT_NART_SAGAS','high','Batraz is the chief warrior-hero of the Narts (Colarusso 2002).'),
 ('ENT_NART_SATANA','member_of','ENT_NART_SAGAS','high','Satana is the matriarch of the central Nart family (Colarusso 2002).'),
 ('ENT_NART_SOSRUKO','member_of','ENT_NART_SAGAS','high','Sosruko/Soslan is a leading Nart culture-hero (Colarusso 2002).'),
 ('ENT_NART_SYRDON','member_of','ENT_NART_SAGAS','high','Syrdon is the resident trickster among the Narts (Colarusso 2002).'),
 ('ENT_NART_SATANA','parent_of','ENT_NART_BATRAZ','medium','In Ossetian tradition Satana fosters and is closely associated as mother-figure to the Nart heroes including Batraz (Dumézil; Colarusso 2002).'),
 ('ENT_NART_KURDALAGON','associated_with','ENT_NART_BATRAZ','high','The smith Kurdalagon tempers Batraz like steel in his celestial forge (Dumézil; Colarusso 2002).'),
 ('ENT_NART_KURDALAGON','associated_with','ENT_NART_SOSRUKO','medium','Kurdalagon tempers the stone-born Soslan/Sosruko in his forge, making him invulnerable (Colarusso 2002).'),
 ('ENT_NART_UASTYRDZHI','presides_over','ENT_NART_SAGAS','medium','Uastyrdzhi is the rider-god patronizing the warrior Narts and intervening in the saga cycle (Dumézil).'),
 ('ENT_NART_UASTYRDZHI','syncretized_with','ENT_SAINT_GEORGE','high','The Ossetian rider-god Uastyrdzhi is syncretized with Saint George, his name and feast (Jeoryguba) deriving from the Christian saint (Dumézil; Colarusso 2002).'),
 ('ENT_NART_BATRAZ','aligned_with','ENT_SCYTH_SWORD_ARES','medium','Dumézil derives Batraz''s steel sword (cast into the sea at his death) from the Scytho-Sarmatian sword-cult that Herodotus (4.62) reports as the akinakes/Sword-Ares; Batraz continues this war-god complex in the Ossetian (Alanic) descendant tradition.'),
 ('ENT_NART_SYRDON','aligned_with','ENT_NOR_LOKI','medium','Comparative mythology (Dumézil school) treats the discord-sowing, malicious trickster Syrdon as the Nart functional cognate of the Norse trickster Loki (Colarusso 2002; Dumézil).');
